# TARS 개발 도구 층(TP-M4 plan 결정 E). Debian의 posix_local scheme과 같은 일을 한다 — 이 python으로 root가 깐 것은
# /usr/local로 간다(`sudo pip install x` → /usr/local/lib/python3.15/site-packages, 실행 파일은 /usr/local/bin). 그 자리는
# python의 판(3.15.x)에 묶이지 않아 묶음이 새 판으로 바뀌어도 남는다. venv(sys.prefix != sys.base_prefix)와 --user는 그대로다.
import sys

if sys.prefix == sys.base_prefix:
    import site
    import sysconfig

    _LOCAL = "/usr/local"
    _scheme = dict(sysconfig._INSTALL_SCHEMES["posix_prefix"])
    for _key in ("purelib", "platlib", "scripts", "data"):
        _scheme[_key] = _scheme[_key].replace("{platbase}", _LOCAL).replace("{base}", _LOCAL)
    sysconfig._INSTALL_SCHEMES["tars_local"] = _scheme
    _preferred = sysconfig.get_preferred_scheme

    def _tars_preferred(key):
        return "tars_local" if key == "prefix" else _preferred(key)

    sysconfig.get_preferred_scheme = _tars_preferred
    site.addsitedir(sysconfig.get_paths("tars_local")["purelib"])
